R=C=20
g=[[0]*C for _ in range(R)]
ones=[(2,6),(3,19),(4,5),(7,1),(8,19),(12,9),(17,13),(19,15)]
for r in range(2,9):
    for c in range(9,16): g[r][c]=2
# Extend to edges on each side where no marker lies in that outward row/column
for r in range(2,9):
    if not any(rr==r and cc<9 for rr,cc in ones):
        for c in range(0,9): g[r][c]=2
    if not any(rr==r and cc>15 for rr,cc in ones):
        for c in range(16,20): g[r][c]=2
for c in range(9,16):
    if not any(rr<2 and cc==c for rr,cc in ones):
        for r in range(0,2): g[r][c]=2
    if not any(rr>8 and cc==c for rr,cc in ones):
        for r in range(9,20): g[r][c]=2
for r,c in ones: g[r][c]=1
import json
out=json.dumps(g,separators=(',',':'))
print(out)
print('\n'.join(' '.join(map(str,row)) for row in g))
